mapper.select:
select count(*)
from tb_screen_sum
where person_id=#{personId} and `year`=#{year} and screen_type=#{screenType}

select tss.*
from tb_screen_sum tss
left join tb_screen_person tsp on tss.person_id = tsp.id
where tsp.screen_point=#{screenPoint}
and tss.year=#{year}
and tsp.deleted=0

select max(screen_Order)
from tb_screen_sum
where id_num=${idNum} and `year`=${year} and screen_type=${screenType}

select id ,person_id personId,sync_id syncId,id_num idNum,year,screen_type screenType,screen_Order screenOrder,collect_id collectId,ppd_id ppdId,chest_radiograph_id chestRadiographId,computed_tomography_id computedTomographyId,cur_finish curFinish
from tb_screen_sum
where id_num=${idNum} and `year`=${year} and screen_type=${screenType}
and screen_order=(
    select max(screen_Order)
    from tb_screen_sum
    where id_num=${idNum} and `year`=${year} and screen_type=${screenType}
    )

select ifnull(count(*),0)
from tb_screen_sum
where id_num=${idNum} and `year`=${year} and screen_type=${screenType}

select *
from tb_screen_sum
where id_num=${idNum} and `year`=${year} and screen_type=${screenType}
